package com.bank.dispute;

import java.math.BigDecimal;
import java.util.Arrays;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class ChequeVerifyDemo {
    private static final Logger log = Logger.getLogger(ChequeVerifyDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        List<BigDecimal> cleared = Arrays.asList(
            new BigDecimal("1500.00"),
            new BigDecimal("9800.00"),
            new BigDecimal("640.00"));

        Account priya = new Account("CUR3001", "Priya Sharma", cleared);
        ChequeVerifier verifier = new ChequeVerifier();

        BigDecimal disputed = new BigDecimal("9800");
        boolean exists = verifier.contains(priya.getAmounts(), disputed);
        log.info(() -> "Cheque Rs." + disputed + " cleared on "
                + priya.getAccountId() + "? " + (exists ? "YES" : "NO"));
    }
}

class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
