package com.bank.dispute;

import java.math.BigDecimal;
import java.util.List;

class ChequeVerifier {

    // Linear search with early exit: true at first match, false if none.
    boolean contains(List<BigDecimal> amounts, BigDecimal target) {
        if (amounts == null) return false;
        for (BigDecimal current : amounts) {
            if (target.compareTo(current) == 0) {   // value equality
                return true;                         // early exit — found it
            }
        }
        return false;                                // checked all, not found
    }
}
